const raw = $input.first().json;
let body;
if (raw.body && raw.body.data) {
  body = JSON.parse(raw.body.data);
} else if (raw.data && typeof raw.data === 'string') {
  body = JSON.parse(raw.data);
} else {
  body = raw.body || raw;
}
const errors = [];

if (!body.account || !body.account.accountNumber) errors.push('Account number is required');
if (!body.contact) errors.push('Contact information is required');
else {
  if (!body.contact.firstName) errors.push('First name is required');
  if (!body.contact.lastName) errors.push('Last name is required');
  if (!body.contact.email) errors.push('Email is required');
}
if (!body.productLines || !Array.isArray(body.productLines) || body.productLines.length === 0) {
  errors.push('At least one product line is required');
} else if (body.productLines.length > 10) {
  errors.push('Maximum 10 product lines allowed');
} else {
  body.productLines.forEach((line, i) => {
    if (!line.productNumber) errors.push(`Line ${i+1}: Product number is required`);
    if (!line.quantity || line.quantity < 1) errors.push(`Line ${i+1}: Valid quantity is required`);
    if (!line.requestType || (line.requestType !== 'Credit' && line.requestType !== 'Complaint')) errors.push(`Line ${i+1}: Request type must be Credit or Complaint`);
    if (!line.issueClassification) errors.push(`Line ${i+1}: Issue classification is required`);
  });
}

if (errors.length > 0) {
  return [{ json: { validationError: true, errors, message: errors.join('; ') } }];
}

const totalQty = body.productLines.reduce((sum, l) => sum + (parseInt(l.quantity) || 0), 0);
body.totalQuantity = totalQty;
body.totalLineItems = body.productLines.length;

return [{ json: body }];

const searchResult = $input.first().json;
const store = $getWorkflowStaticData('global');
const original = $('Validate Payload').first().json;

store.companyId = searchResult.results[0].id;
store.companyName = searchResult.results[0].properties.name || '';
store.payload = original;

return [{ json: {
  email: original.contact.email,
  firstname: original.contact.firstName,
  lastname: original.contact.lastName,
  phone: original.contact.phone || ''
} }];

const store = $getWorkflowStaticData('global');
const upsertResponse = $('Upsert Contact').first().json;
const original = store.payload;

const contactId = upsertResponse.results[0].id;
store.contactId = contactId;

const lines = original.productLines;
const linesSummary = lines.map((l, i) =>
  `Line ${i+1}: ${l.productNumber} (${l.productDescription || ''}) × ${l.quantity} — ${l.issueClassification} — ${l.requestType}${l.notes ? ' — ' + l.notes : ''}`
).join('\n');

const summary = `Request: ${lines.length > 0 ? lines[0].requestType : 'Credit'} — Acct #${original.account.accountNumber} (${original.account.accountName || store.companyName})\n${linesSummary}${original.ticketNotes ? '\nNotes: ' + original.ticketNotes : ''}`;

store.creditSummary = summary;

const up = store.uploadedUrls || {};
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const lineBlocks = lines.map((l, i) => {
  const photos = up[String(l.lineNumber)] || [];
  const photoHtml = photos.length ? photos.map((u, n) => `<a href="${esc(u)}">Photo ${n + 1}</a>`).join(', ') : '';
  const rows = [];
  rows.push(`<li><strong>Item No.:</strong> ${esc(l.productNumber)}${l.productDescription ? ' (' + esc(l.productDescription) + ')' : ''}</li>`);
  rows.push(`<li><strong>Lot Code:</strong> ${esc(l.julianCode) || '&mdash;'}</li>`);
  rows.push(`<li><strong>Quantity:</strong> ${esc(l.quantity)}</li>`);
  rows.push(`<li><strong>Request Type:</strong> ${esc(l.requestType)}</li>`);
  rows.push(`<li><strong>Complaint Type:</strong> ${esc(l.issueClassification)}</li>`);
  if (photoHtml) rows.push(`<li><strong>Photos:</strong> ${photoHtml}</li>`);
  if (l.notes) rows.push(`<li><strong>Notes:</strong> ${esc(l.notes)}</li>`);
  return `<p style="margin:12px 0 4px;"><strong>Product Line ${i + 1}</strong></p><ul style="margin:0 0 8px;">${rows.join('')}</ul>`;
}).join('');

const summaryHtml = `<p><strong>Request:</strong> ${lines.length > 0 ? esc(lines[0].requestType) : 'Credit'} &mdash; Acct #${esc(original.account.accountNumber)} (${esc(original.account.accountName || store.companyName)})</p>${original.account.invoiceNumber ? '<p><strong>Invoice #:</strong> ' + esc(original.account.invoiceNumber) + '</p>' : ''}${lineBlocks}${original.ticketNotes ? '<p><strong>Notes:</strong> ' + esc(original.ticketNotes) + '</p>' : ''}`;
store.creditSummaryHtml = summaryHtml;

const uploadedUrls = store.uploadedUrls || {};
const allPhotos = Object.keys(uploadedUrls)
  .sort((a, b) => Number(a) - Number(b))
  .flatMap(lineNum => uploadedUrls[lineNum].map(url => url))
  .join('\n');

const now = new Date(original.submittedAt);
const estDate = new Date(now.toLocaleString('en-US', { timeZone: 'America/New_York' }));
const yy = String(estDate.getFullYear()).slice(2);
const mm = String(estDate.getMonth() + 1).padStart(2, '0');
const dd = String(estDate.getDate()).padStart(2, '0');
const submissionDate = `${yy}-${mm}-${dd}`;

const allComplaint = lines.length > 0 && lines.every(l => l.requestType === 'Complaint');
const subjectPrefix = allComplaint ? 'Complaint' : 'Credit Request';

return [{ json: {
  subject: `${subjectPrefix}: ${original.account.accountNumber} - ${submissionDate}`,
  account__: original.account.accountNumber,
  company_name: original.account.accountName || store.companyName,
  invoice: original.account.invoiceNumber || '',
  credit_summary: summary,
  credit_summary_html: summaryHtml,
  hs_pipeline: '912400389',
  hs_pipeline_stage: '1385996039',
  photosdocumentation: allPhotos
} }];

const store = $getWorkflowStaticData('global');
const ticket = $input.first().json;
store.ticketId = ticket.id;
return [{ json: { ticketId: ticket.id, contactId: store.contactId, companyId: store.companyId } }];

const store = $getWorkflowStaticData('global');
const lines = store.payload.productLines;
const uploadedUrls = store.uploadedUrls || {};

const totalCreditQuantity = lines
  .filter(l => l.requestType === 'Credit')
  .reduce((sum, l) => sum + (parseInt(l.quantity) || 0), 0);

const hasComplaint = lines.some(l => l.requestType === 'Complaint');

store.totalCreditQuantity = totalCreditQuantity;
store.hasComplaint = hasComplaint;

return lines.map(l => ({
  json: {
    ...l,
    uploadedPhotoUrls: uploadedUrls[String(l.lineNumber)] || []
  }
}));

const store = $getWorkflowStaticData('global');
const line = $json;
const totalCreditQty = store.totalCreditQuantity;

let itemStage;

if (line.requestType === 'Complaint') {
  itemStage = '1388087302';
} else if (line.requestType === 'Credit') {
  itemStage = totalCreditQty >= 10 ? '1386096010' : '1388087301';
} else {
  itemStage = '1388087301';
}

const accountNumber = $('Validate Payload').first().json.account.accountNumber;
const accountName = $('Validate Payload').first().json.account.accountName || store.companyName || '';
const submittedAt = $('Validate Payload').first().json.submittedAt;
const d = new Date(submittedAt);
const e = new Date(d.toLocaleString('en-US', { timeZone: 'America/New_York' }));
const formattedDate = String(e.getFullYear()).slice(2) + '-' + String(e.getMonth()+1).padStart(2,'0') + '-' + String(e.getDate()).padStart(2,'0');

return [{ json: {
  properties: {
    item_name: accountNumber + ' - ' + formattedDate + ' - ' + line.productNumber,
    erp_account_number: String(accountNumber),
    company_name: store.companyName || accountName,
    item_no_: line.productNumber,
    item_description: line.productDescription || '',
    julian_code: line.julianCode || '',
    quantity: String(line.quantity),
    request_type: line.requestType,
    complaint_type: line.issueClassification,
    line_notes: line.notes || '',
    photosdocumentation: (line.uploadedPhotoUrls || []).join('\n'),
    hs_pipeline: '912368291',
    hs_pipeline_stage: itemStage
  }
} }];

const store = $getWorkflowStaticData('global');
if (!store.itemIds) {
  store.itemIds = [];
}

const createItemResult = $('Create Item Record').first().json;
let itemId = null;

if (createItemResult && createItemResult.id) {
  itemId = createItemResult.id;
  store.itemIds.push(itemId);
  return [{ json: { itemId: itemId, success: true, totalCaptured: store.itemIds.length, allIds: store.itemIds } }];
} else {
  return [{ json: { error: 'Failed to capture item ID', responseKeys: createItemResult ? Object.keys(createItemResult) : 'null', totalCaptured: store.itemIds.length, allIds: store.itemIds } }];
}

const webhookBinary = $('Webhook').first().binary || {};
const store = $getWorkflowStaticData('global');

const filesToUpload = [];

for (const key of Object.keys(webhookBinary)) {
  const match = key.match(/^photo_line(\d+)_file(\d+)$/);
  if (!match) {
    const legacyMatch = key.match(/^photos_line_(\d+)/);
    if (!legacyMatch) continue;
    const lineNum = legacyMatch[1];
    filesToUpload.push({
      json: {
        lineNum: lineNum,
        fileName: webhookBinary[key].fileName || key
      },
      binary: { data: webhookBinary[key] }
    });
    continue;
  }
  const lineNum = match[1];
  filesToUpload.push({
    json: {
      lineNum: lineNum,
      fileName: webhookBinary[key].fileName || key
    },
    binary: { data: webhookBinary[key] }
  });
}

store.uploadedUrls = {};

if (filesToUpload.length === 0) {
  return [{ json: { hasFiles: false } }];
}

return filesToUpload.map(f => ({
  json: { ...f.json, hasFiles: true },
  binary: f.binary
}));

const store = $getWorkflowStaticData('global');
const uploadResult = $input.first().json;
const lineNum = $('File Upload Loop').first().json.lineNum;

if (!store.uploadedUrls) store.uploadedUrls = {};
if (!store.uploadedUrls[lineNum]) store.uploadedUrls[lineNum] = [];
store.uploadedUrls[lineNum].push(uploadResult.url || uploadResult.defaultDisplayUrl || '');

return [{ json: { stored: true, lineNum } }];

const store = $getWorkflowStaticData('global');
const payload = store.payload;
const lines = payload.productLines;
const totalQty = payload.totalQuantity;

const hasComplaint = lines.some(l => l.requestType === 'Complaint');

let ticketStage, itemStage;

if (hasComplaint) {
  ticketStage = '1387983014';
  itemStage = '1388087302';
  store.routeType = 'CAPA';
} else if (totalQty >= 10) {
  ticketStage = '1385996039';
  itemStage = '1386096010';
  store.routeType = 'Verification';
} else {
  ticketStage = '1387983013';
  itemStage = '1388087301';
  store.routeType = 'Credit Decision';
}

store.ticketStage = ticketStage;
store.itemStage = itemStage;

return [{ json: { ticketStage, itemStage, ticketId: store.ticketId, routeType: store.routeType } }];

const store = $getWorkflowStaticData('global');
const ticketId = store.ticketId;
if (!ticketId) {
  throw new Error('Ticket ID not found in workflow state');
}
return [{ json: { ticketId: ticketId } }];

const items = $input.first().json.results || [];
const store = $getWorkflowStaticData('global');
const STAGE_ORDER = {
  '1386096010': 0, // Verification
  '1388087301': 1, // Credit Decision
  '1388087302': 2, // CAPA
  '1386096011': 3  // Closed
};
let lowestStage = null, lowestRank = Infinity;
const stages = [];
for (const item of items) {
  const stage = String((item.properties && item.properties.hs_pipeline_stage) || '');
  if (!stage) continue;
  stages.push(stage);
  const rank = STAGE_ORDER[stage];
  if (rank !== undefined && rank < lowestRank) { lowestRank = rank; lowestStage = stage; }
}
if (lowestStage === null) {
  return [{ json: { lowestStage: store.itemStage, message: 'No recognized item stages, using determined stage' } }];
}
return [{ json: { lowestStage, itemCount: items.length, allStages: stages, success: true } }];

const store = $getWorkflowStaticData('global');
const itemStage = $json.lowestStage;
const stageMapping = {
  '1386096010': '1385996039',
  '1388087301': '1387983013',
  '1388087302': '1387983014',
  '1386096011': '1385996040'
};

const ticketStage = stageMapping[itemStage] || itemStage;

if (!stageMapping[itemStage]) {
  console.warn(`Unknown item stage ${itemStage}, using as-is`);
}

return [{ json: { ticketStage: ticketStage, itemStage: itemStage, ticketId: store.ticketId } }];

const store = $getWorkflowStaticData('global');
const itemIds = store.itemIds || [];
const itemStage = $input.first().json.itemStage;
const productLineCount = store.payload.productLines.length;

if (!itemIds || itemIds.length === 0) {
  return [{ json: { error: 'No item IDs captured', itemIdsCount: 0, productLinesCount: productLineCount } }];
}

if (itemIds.length !== productLineCount) {
  return [{ json: { warning: 'Item ID count mismatch', itemIdsCount: itemIds.length, productLinesCount: productLineCount, itemIds: itemIds } }];
}

const requestBody = {
  inputs: itemIds.map(id => ({
    id: String(id),
    properties: {
      hs_pipeline_stage: itemStage
    }
  }))
};

return [{ json: { requestBody, itemIdsCount: itemIds.length, stageName: $input.first().json.routeType } }];
